   let mut mean=0;for i in 0..before.len(){mean=add(mean,mul(after[i]-before[i],weights[i]as i128)?)?;}signs.insert(if mean<0{-1}else if mean>0{1}else{0});
   let mut contingent_mean=0;for i in 0..before.len(){contingent_mean=add(contingent_mean,mul(contingent[i]-before[i],weights[i]as i128)?)?;}contingent_signs.insert(if contingent_mean<0{-1}else if contingent_mean>0{1}else{0});
   let contingent_hit:u64=contingent.iter().zip(thresholds).zip(weights).filter(|((w,t),_)|*w>*t).map(|(_,w)|*w).sum();if prerequisite{let gain=c["contingentPlan"]["minimumTargetGainPpm"].as_u64().filter(|g|*g>0&&*g<=1000000).ok_or("RANK_CONTINGENT_TARGET")?;need(contingent_hit>=baseline.checked_add(gain).ok_or("RANK_RANGE")?,"RANK_CONTINGENT_TARGET")?;}
   let mut replacement_partial=vec![];for(j,(prior,per_share,n))in contingent_paths.iter().enumerate(){let mut points=BTreeSet::from([0,*n]);for i in 0..prior.len(){if per_share[i]!=0{let crossing=(thresholds[i]-prior[i]).div_euclid(per_share[i]);for q in [crossing-1,crossing,crossing+1]{if q>=0&&q<=*n as i128{points.insert(q as u64);}}}}let mut outcomes=vec![];for q in points{branch_budget=branch_budget.checked_sub(1).ok_or("RANK_PARTIAL_MODEL_BOUND")?;let wealth=prior.iter().zip(per_share).map(|(w,d)|add(*w,mul(*d,q as i128)?)).collect::<Result<Vec<_>>>()?;let hit:u64=wealth.iter().zip(thresholds).zip(weights).filter(|((w,t),_)|*w>*t).map(|(_,w)|*w).sum();outcomes.push(json!({"filledQuantity":q,"strictHitPpm":hit}));}replacement_partial.push(json!({"trancheIndex":j,"previousTranchesAssumedFullyFilled":j,"partialFillTargetBreakpoints":outcomes}));}
   scores.push(json!({"conditionalFullCampaignStrictHitPpm":contingent_hit,"conditionalCampaignExpectedMoneyNumerator":contingent_mean.to_string(),"probabilityId":pi,"fieldId":fi,"baselineStrictHitPpm":baseline,"fullStrictHitPpm":full,"incrementalExpectedMoneyNumerator":mean.to_string(),"denominator":1000000,"partialFillTargetBreakpoints":partial,"conditionalReplacementPartialFillBranches":replacement_partial,"tiesOrExpectedPrize":null}));
